import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    records = []
    start_time = time.time()

    while time.time() - start_time < duration:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        cpu_usage = None

        try:
            system = platform.system()
            if system == "Windows":
                output = subprocess.check_output("wmic cpu get loadpercentage /value", shell=True).decode()
                for line in output.splitlines():
                    if line.startswith("LoadPercentage"):
                        cpu_usage = float(line.split("=")[1].strip())
                        break
            else:
                output = subprocess.check_output("top -bn1 | grep 'Cpu(s)'", shell=True).decode()
                parts = output.replace(",", "").split()
                if "id" in parts:
                    idle_index = parts.index("id") - 1
                    idle = float(parts[idle_index])
                    cpu_usage = 100.0 - idle
        except Exception:
            cpu_usage = None

        records.append({
            "timestamp": timestamp,
            "cpu_usage": cpu_usage
        })

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as log_file:
            json.dump(records, log_file)
        return LOGFILE_PATH
    except IOError:
        return None

