import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.isfile(script_name):
        raise FileNotFoundError(f"Script file not found: {script_name}")

    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    try:
        process = subprocess.run(script_name, shell=True)
        exit_status = process.returncode
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")

    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    result = {
        'start_time': start_time,
        'end_time': end_time,
        'exit_status': exit_status
    }

    try:
        log_dir = os.path.dirname(os.path.abspath(log_file))
        if log_dir:
            os.makedirs(log_dir, exist_ok=True)
        with open(log_file, 'w') as f:
            json.dump(result, f)
    except Exception as e:
        raise RuntimeError(f"Error writing log file: {e}")

    return result

